'use client'

import { useState } from 'react'
import { LogOut } from 'lucide-react'
import { signOut } from 'next-auth/react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'

export default function LogoutDialog() {
  const [open, setOpen] = useState(false)

  const handleLogout = async () => {
    setOpen(false)
    await signOut({ callbackUrl: '/' }) // redirect after logout
  }

  return (
    <>
      <div
        onClick={() => setOpen(true)}
        className="flex items-center gap-3 px-4 py-2 rounded-md cursor-pointer hover:bg-gray-700/60 text-gray-200"
      >
        <LogOut size={20} />
        <span className="text-sm">Log Out</span>
      </div>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="sm:max-w-md bg-white text-black rounded-2xl shadow-lg">
          <DialogHeader className="flex justify-between items-center">
            <DialogTitle className="text-xl font-semibold text-[#4b4744]">
              Confirm Logout
            </DialogTitle>
          </DialogHeader>

          <p className="text-sm text-gray-600 mb-4 text-center">
            Are you sure you want to log out?
          </p>

          <div className="flex justify-center gap-3 ">
            <Button variant="outline" onClick={() => setOpen(false)}>
              No
            </Button>
            <Button
              className="bg-[#797068] hover:bg-[#5f5a56]"
              onClick={handleLogout}
            >
              Yes, Log Out
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}
