'use client'

import {
  LayoutDashboard,
  ShoppingCart,
  Boxes,
  BarChart2,
  Settings,
  BoxIcon,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import LogoutDialog from './LogoutDialog'

const sidebarItems = [
  {
    icon: <LayoutDashboard size={18} />,
    text: 'Dashboard',
    href: '/seller-dashboard/dashboard',
  },
  {
    icon: <ShoppingCart size={18} />,
    text: 'Order',
    href: '/seller-dashboard/order',
  },
  {
    icon: <Boxes size={18} />,
    text: 'Active Product List',
    href: '/seller-dashboard/active-products',
  },
  {
    icon: <BoxIcon size={18} />,
    text: 'Pending Product List',
    href: '/seller-dashboard/products',
  },
  {
    icon: <BarChart2 size={18} />,
    text: 'My Sales',
    href: '/seller-dashboard/sales',
  },
  {
    icon: <Settings size={18} />,
    text: 'Settings',
    href: '/seller-dashboard/settings',
  },
]

function SidebarItem({
  icon,
  text,
  href,
  active,
}: {
  icon: React.ReactNode
  text: string
  href: string
  active?: boolean
}) {
  return (
    <Link href={href}>
      <div
        className={`flex items-center gap-3 px-4 py-2.5 rounded-lg cursor-pointer transition-all duration-150 ${
          active
            ? 'bg-[#E7F3F0] text-[#71A899] font-semibold'
            : 'text-[#6C757D] hover:bg-[#F1F5F9] hover:text-[#71A899]'
        }`}
      >
        {icon}
        <span className="text-sm">{text}</span>
      </div>
    </Link>
  )
}

export default function Sidebar() {
  const pathname = usePathname()

  return (
    <aside className="w-[250px] bg-[#FFFFFF] border-r border-gray-200 min-h-screen flex flex-col">
      <div className="h-[80px] flex items-center justify-center border-b border-gray-200">
        <Image
          src="/images/dashboard_header.png"
          alt="Dashboard Logo"
          width={160}
          height={40}
          priority
          className="object-contain"
        />
      </div>

      <nav className="flex-1 px-4 py-6">
        <div className="space-y-2">
          {sidebarItems.map((item) => (
            <SidebarItem
              key={item.text}
              {...item}
              active={pathname === item.href}
            />
          ))}
        </div>
      </nav>

      <div className="mt-auto border-t border-gray-200 px-4 py-4">
        <LogoutDialog />
      </div>
    </aside>
  )
}
